import subprocess
import csv
import os
def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError("Commands file not found")
    os.makedirs(output_dir_path, exist_ok=True)
    commands = []
    with open(commands_file_path, 'r') as f:
        reader = csv.reader(f)
        for row in reader:
            if row:
                commands.append(row[0])
    output_files = []
    for idx, cmd in enumerate(commands):
        output_file = os.path.join(output_dir_path, f'command_{idx}_output.txt')
        try:
            result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=30)
            with open(output_file, 'w') as f:
                if result.returncode == 0:
                    f.write(result.stdout)
                else:
                    f.write(f"Error: {result.stderr}\nExit code: {result.returncode}")
        except subprocess.TimeoutExpired:
            with open(output_file, 'w') as f:
                f.write("Error: Command timed out after 30 seconds\nExit code: -1")
        except Exception as e:
            with open(output_file, 'w') as f:
                f.write(f"Error: {str(e)}\nExit code: -1")
        output_files.append(output_file)
    return output_files

import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    process_found = False
    for proc in psutil.process_iter(['name']):
        if proc.info['name'] == process_name:
            process_found = True
            proc.terminate()
            time.sleep(0.5)
            break
    subprocess.Popen(process_name)
    if process_found:
        return f"Process found. Restarting {process_name}."
    else:
        return f"Process not found. Starting {process_name}."

import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == "Windows":
        command = ["start", url]
    elif system == "Darwin":
        command = ["open", url]
    else:
        command = ["xdg-open", url]
    process = subprocess.Popen(command)
    time.sleep(0.1)
    return_code = process.poll()
    if return_code is None:
        return 0
    else:
        return return_code

import subprocess
import time
import threading
def task_func(file_list):
    exit_codes = [None] * len(file_list)
    def run_file(index, file_path):
        try:
            result = subprocess.run(file_path, shell=True)
            exit_codes[index] = result.returncode
        except Exception:
            exit_codes[index] = -1
    threads = []
    for i, f in enumerate(file_list):
        t = threading.Thread(target=run_file, args=(i, f))
        threads.append(t)
        t.start()
    for t in threads:
        t.join()
    return exit_codes

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder) or not os.path.exists(dst_folder):
        return {'success': False, 'message': 'Source or destination folder does not exist', 'failed_files': []}
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    for file in files:
        if os.path.isfile(file):
            try:
                subprocess.run(['gzip', '-f', file], check=True)
                gz_file = file + '.gz'
                if os.path.exists(gz_file):
                    shutil.move(gz_file, os.path.join(dst_folder, os.path.basename(gz_file)))
            except Exception:
                failed_files.append(os.path.basename(file))
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully' if success else 'Some files failed to compress or move'
    return {'success': success, 'message': message, 'failed_files': failed_files}

